package jv;

public class Smallest {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a=10,b=20,c=30;
		if(a>b || a>c)
		{
			System.out.println("a is smaller");
		}
		else if(b>a ||b>c )
		{
			System.out.println("b is smaller");
		}
		else
		{
			System.out.println("c is smaller");
		}

	}

}
